import wordmarkUrl from '../../brand/logo-wordmark.svg';

/**
 * Aspect ratio of `brand/logo-wordmark.svg`: the file keeps 1368:401 on purpose (`brand-sync.test.ts`), with the
 * pill left-aligned at 36 of the 44 px head height, so this box fits the sidebar without a change.
 */
const ASPECT = 1368 / 401;

/**
 * The Nemo wordmark: the mark and "NEMO" in the contrast colour on an accent pill. Same drawing as the README
 * banner; generated by `design/logo-v2` (`node export.mjs`). It carries its own colours (the accent token's
 * light and dark values, switched by the system colour scheme), so it works on light and dark surfaces.
 */
export function Wordmark({ height = 28, title }: { height?: number; title?: string }) {
  return (
    <img
      src={wordmarkUrl}
      alt={title ?? ''}
      height={height}
      width={Math.round(height * ASPECT)}
      draggable={false}
      aria-hidden={title ? undefined : true}
    />
  );
}
